using System;
using System.Collections.Generic;
using System.IO;
using WtTactical;

class CoreTests {
    static int pass, fail;
    static void Check(string name, Action test) {
        try { test(); pass++; Console.WriteLine("PASS " + name); }
        catch(Exception e) { fail++; Console.WriteLine("FAIL " + name + ": " + e.Message + (e.InnerException==null?"":" / "+e.InnerException.Message)); }
    }
    static void Equal(double expected, double actual) { if (Math.Abs(expected-actual)>0.000001) throw new Exception("Expected " + expected + ", got " + actual); }
    static void Assert(bool value) { if(!value) throw new Exception("Assertion failed"); }
    static void Reject(Action test) { bool threw=false; try {test();} catch(ArgumentException){threw=true;} Assert(threw); }
    static MapLibrary Sample() { return new MapLibrary { Schema=1, Maps=new List<MapDefinition> { new MapDefinition {Id="test", Pins=new List<Pin>{new Pin{Id="p",X=.5,Y=.5,Kind="sniper"}},Routes=new List<Route>()} } }; }
    static int Main(string[] args) {
        Check("crop projects known landmark", delegate {var p=new Viewport{X0=.25,Y0=.1,X1=.75,Y1=.9}.Project(.5,.3,400,200);Equal(200,p[0]);Equal(50,p[1]);});
        Check("crop inverse preserves source coordinate", delegate {var p=new Viewport{X0=.25,Y0=.1,X1=.75,Y1=.9}.Unproject(200,50,400,200);Equal(.5,p[0]);Equal(.3,p[1]);});
        Check("offscreen remains offscreen for clipping", delegate {var p=new Viewport{X0=.25,X1=.75}.Project(0,.5,400,400);Equal(-200,p[0]);});
        Check("invalid crop and NaN rejected", delegate {Reject(delegate{new Viewport{X0=.8,X1=.2}.Validate();});Reject(delegate{new Viewport{X1=double.NaN}.Validate();});Reject(delegate{new Viewport().Project(.5,.5,0,10);});});
        Check("fingerprints match exactly", delegate {var b=new Binding{Fingerprint="abc",MapId="one",View=new Viewport()};Assert(BindingGate.Match("abc",new[]{b})==b);Assert(BindingGate.Match("abd",new[]{b})==null);Assert(BindingGate.Match(null,new[]{b})==null);});
        Check("ambiguous bindings fail closed", delegate {Assert(BindingGate.Match("a",new[]{new Binding{Fingerprint="a",MapId="one",View=new Viewport()},new Binding{Fingerprint="a",MapId="two",View=new Viewport()}})==null);});
        Check("live authorization rejects wrong map crop or session", delegate {var bindings=new[]{new Binding{Fingerprint="abc",MapId="one",View=new Viewport()}};Assert(BindingGate.CanDisplay("abc","7","abc:7","one",new Viewport(),bindings));Assert(!BindingGate.CanDisplay("abc","8","abc:7","one",new Viewport(),bindings));Assert(!BindingGate.CanDisplay("abc","7","abc:7","two",new Viewport(),bindings));Assert(!BindingGate.CanDisplay("abc","7","abc:7","one",new Viewport{X0=.1},bindings));Assert(!BindingGate.CanDisplay(null,"7","abc:7","one",new Viewport(),bindings));});
        Check("confirmation cannot cross a map session or calibration change",delegate {var a=new Profile{MapId="test",Width=300};var b=new Profile{MapId="test",Width=300};Assert(BindingGate.CanConfirm("a:1","a:1",a,b,true));Assert(!BindingGate.CanConfirm("a:1","a:2",a,b,true));b.Width=301;Assert(!BindingGate.CanConfirm("a:1","a:1",a,b,true));b.Width=300;b.MapId="other";Assert(!BindingGate.CanConfirm("a:1","a:1",a,b,true));Assert(!BindingGate.CanConfirm("a:1",null,a,b,true));Assert(!BindingGate.CanConfirm("a:1","a:1",a,a,false));});
        Check("earlier polling activation cannot mutate a later mode",delegate{var gate=new ActivationGate();gate.SetEnabled(true);int first=gate.Generation;Assert(gate.Accept(first));gate.SetEnabled(false);Assert(!gate.Accept(first));gate.SetEnabled(true);Assert(!gate.Accept(first));Assert(gate.Accept(gate.Generation));gate.Close();Assert(!gate.Accept(gate.Generation));});
        Check("malformed profiles and bindings rejected before UI use",delegate{var l=Sample();var d=new UserData();d.Profiles.Add(null);Reject(delegate{Validation.User(d,l);});d.Profiles.Clear();d.Profiles.Add(new Profile{MapId="test",View=null});Reject(delegate{Validation.User(d,l);});d.Profiles[0].View=new Viewport();d.Profiles[0].Left=double.NaN;Reject(delegate{Validation.User(d,l);});d.Profiles.Clear();d.Bindings.Add(null);Reject(delegate{Validation.User(d,l);});d.Bindings[0]=new Binding{Fingerprint="abc",MapId="missing",View=new Viewport()};Reject(delegate{Validation.User(d,l);});});
        Check("filtered annotations keep their original numbers",delegate{var all=new[]{new Pin{Id="p",Kind="position"},new Pin{Id="d",Kind="danger"}};var shown=AnnotationLayout.Visible(all,false,true);Assert(shown.Count==1);Assert(shown[0].Number==2&&shown[0].Pin.Id=="d");});
        Check("saved calibration reused only on the same display layout",delegate{var p=new Profile{MapId="test",PositionVerified=true,DisplayStamp="display-a"};Assert(CalibrationPolicy.CanReuse(p,"display-a"));Assert(!CalibrationPolicy.CanReuse(p,"display-b"));p.DisplayStamp=null;Assert(!CalibrationPolicy.CanReuse(p,"display-a"));Assert(!CalibrationPolicy.CanReuse(null,"display-a"));});
        Check("different mission layout does not inherit a previous crop",delegate{var p=new Profile{MapId="test",PositionVerified=true,DisplayStamp="display",MapLayoutStamp="layout-a"};Assert(CalibrationPolicy.CanReuse(p,"display","layout-a"));Assert(!CalibrationPolicy.CanReuse(p,"display","layout-b"));var d=new UserData();d.Profiles.Add(p);d.Profiles.Add(new Profile{MapId="test",DisplayStamp="display",MapLayoutStamp="layout-b"});Validation.User(d,Sample());});
        Check("custom routes persist and reject incomplete lines",delegate{var d=new UserData();d.Routes.Add(new RouteRecord{MapId="test",Path=new Route{Id="u-r",Kind="flank",Title="侧翼",Source="user",Points=new[]{new[]{.1,.2},new[]{.4,.5}}}});Validation.User(d,Sample());var path=Path.GetTempFileName();try{JsonStore.Save(path,d);var loaded=JsonStore.Load<UserData>(path);Assert(loaded.Routes[0].Path.Title=="侧翼");Equal(.5,loaded.Routes[0].Path.Points[1][1]);}finally{File.Delete(path);if(File.Exists(path+".bak"))File.Delete(path+".bak");}d.Routes[0].Path.Points=new[]{new[]{.1,.2}};Reject(delegate{Validation.User(d,Sample());});});
        Check("user annotation saved and restored", delegate {var dir=Path.Combine(Path.GetTempPath(),"wt-overlay-test-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var path=Path.Combine(dir,"user.json");var d=new UserData();d.Markers.Add(new PinRecord{MapId="one",Marker=new Pin{Id="p",Title="危险区域",Kind="danger",X=.2,Y=.7,Radius=.03}});JsonStore.Save(path,d);var loaded=JsonStore.Load<UserData>(path);Assert(loaded.Markers[0].Marker.Title=="危险区域");Equal(.7,loaded.Markers[0].Marker.Y);d.Markers[0].Marker.Y=.4;JsonStore.Save(path,d);Equal(.4,JsonStore.Load<UserData>(path).Markers[0].Marker.Y);Equal(.7,JsonStore.Load<UserData>(path+".bak").Markers[0].Marker.Y);}finally{Directory.Delete(dir,true);}});
        Check("corrupt JSON is preserved and reported", delegate {var path=Path.GetTempFileName();try{File.WriteAllText(path,"{broken");bool threw=false;try{JsonStore.Load<UserData>(path);}catch(InvalidDataException){threw=true;}Assert(threw);Assert(File.ReadAllText(path)=="{broken");}finally{File.Delete(path);}});
        Check("invalid map coordinate rejected", delegate {var l=Sample();l.Maps[0].Pins[0].X=1.1;Reject(delegate{Validation.Library(l);});});
        Check("duplicate map IDs rejected", delegate {var l=Sample();l.Maps.Add(l.Maps[0]);Reject(delegate{Validation.Library(l);});});
        Check("invalid route points rejected", delegate {var l=Sample();l.Maps[0].Routes.Add(new Route{Id="r",Points=new[]{new[]{.1,.2}}});Reject(delegate{Validation.Library(l);});});
        if(args.Length>0) Check("real map library validated", delegate {var l=JsonStore.Load<MapLibrary>(args[0]);Validation.Library(l);Assert(l.Maps.Count>=50);int p=0,r=0;foreach(var m in l.Maps){p+=m.Pins.Count;r+=m.Routes.Count;}Console.WriteLine("MAPS="+l.Maps.Count+" PINS="+p+" ROUTE_SEGMENTS="+r);Assert(p>0&&r>0);});
        Console.WriteLine("RESULT "+pass+" passed, "+fail+" failed");return fail==0?0:1;
    }
}
